sed -i 's/val packages = pm.getInstalledApplications(PackageManager.GET_META_DATA)/try {\n                val packages = pm.getInstalledApplications(PackageManager.GET_META_DATA)\n                val appList = packages.mapNotNull { appInfo ->\n                    if (pm.getLaunchIntentForPackage(appInfo.packageName) != null) {\n                        InstalledApp(\n                            name = pm.getApplicationLabel(appInfo).toString(),\n                            packageName = appInfo.packageName,\n                            applicationInfo = appInfo\n                        )\n                    } else null\n                }.sortedBy { it.name }\n                _installedApps.value = appList\n            } catch (e: Throwable) { e.printStackTrace() }/g' app/src/main/java/com/example/viewmodels/GameViewModel.kt
